code_es:
CREATE TABLE employees (id INTEGER, name TEXT, manager_id INTEGER);
INSERT INTO employees VALUES (1,'CEO',NULL);
INSERT INTO employees VALUES (2,'Manager',1);
INSERT INTO employees VALUES (3,'Dev',2);
WITH ___ hierarchy AS (
  SELECT id, name, manager_id, 0 as level FROM employees WHERE manager_id IS NULL
  UNION ALL
  SELECT e.id, e.name, e.manager_id, h.level + 1 FROM employees e INNER JOIN hierarchy h ON e.manager_id = h.id
)
SELECT * FROM hierarchy;

